SELECT post_id, board_id, author_id, title, content, view_count, like_count, comment_count, is_top, status, create_time, update_time FROM forum_post
status = 1 AND board_id = #{boardId}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY is_top DESC, create_time DESC LIMIT #{offset}, #{size}
